import java.lang.reflect.Field;
public class Main {
    record Potion(String type, int potency) {}
    public static void main(String[] args) throws Exception {
        Potion p = new Potion("Mana", 75);
        System.out.println(p.getClass().getSimpleName());
        Field f = p.getClass().getDeclaredField("potency");
        f.setAccessible(true);
        System.out.println(f.get(p));
    }
}

public class Main {
    static class Spell {
        private String name = "Frost";
    }
    public static void main(String[] args) throws Exception {
        Spell spell = new Spell();
        Field f = Spell.class.getDeclaredField("name");
        // setAccessible not called!
        System.out.println(f.get(spell)); // throws IllegalAccessException
    }
}

